29414571683360730	/opt/airflow/dags/crawl_paper_to_kafka_dag.py	2026-03-29 13:34:44.787401+00	from __future__ import annotations\n\nfrom datetime import datetime, timedelta\nimport os\n\nimport requests\nfrom airflow import DAG\nfrom airflow.operators.python import PythonOperator\n\n\ndefault_args = {\n    "owner": "ai-rader",\n    "retries": 2,\n    "retry_delay": timedelta(minutes=5),\n    "email_on_failure": False,\n    "depends_on_past": False,\n    "execution_timeout": timedelta(minutes=20),\n}\n\n\ndef _trigger_arxiv_crawl() -> None:\n    base_url = os.getenv("CRAWLING_API_BASE_URL", "http://host.docker.internal:8002").rstrip("/")\n    url = f"{base_url}/crawl/jobs"\n    payload = {\n        "domain": "paper",\n        "provider": "arxiv_api",\n        "max_articles": 60,\n    }\n    resp = requests.post(url, json=payload, timeout=180)\n    resp.raise_for_status()\n    data = resp.json()\n    print(\n        "crawl done",\n        {\n            "domain": data.get("domain"),\n            "provider": data.get("provider"),\n            "crawled_count": data.get("crawled_count"),\n            "failed_count": data.get("failed_count"),\n            "kafka": (data.get("metadata") or {}).get("kafka"),\n        },\n    )\n\n\nwith DAG(\n    dag_id="crawl_paper_to_kafka",\n    default_args=default_args,\n    schedule_interval="*/30 * * * *",\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,    # 동시 실행 1개로 제한 (크롤링 서버 과부하 방지)\n    tags=["crawl", "paper", "kafka"],\n) as dag:\n    crawl_arxiv = PythonOperator(\n        task_id="crawl_arxiv_cs_ai",\n        python_callable=_trigger_arxiv_crawl,\n    )\n
45398552423348313	/opt/airflow/dags/gold_serving_dag.py	2026-03-29 13:34:44.8104+00	from datetime import datetime, timedelta\n\nfrom airflow import DAG\nfrom airflow.providers.apache.spark.operators.spark_submit import SparkSubmitOperator\n\ndefault_args = {\n    'owner': 'ai-radar',\n    'retries': 2,\n    'retry_delay': timedelta(minutes=5),\n    'email_on_failure': False,\n    'depends_on_past': False,\n    'execution_timeout': timedelta(hours=12),  # 로컬 AI 서버 기준 충분한 여유\n}\n\nSPARK_CONF = {\n    'spark.master': 'spark://spark-master:7077',\n    'spark.executor.memory': '1g',\n    'spark.executor.cores': '1',\n    'spark.executor.instances': '2',   # OOM 방지 (15g 서버 기준 2개 제한)\n    'spark.driver.memory': '1g',\n    'spark.sql.extensions': 'io.delta.sql.DeltaSparkSessionExtension',\n    'spark.sql.catalog.spark_catalog': 'org.apache.spark.sql.delta.catalog.DeltaCatalog',\n}\n\nwith DAG(\n    dag_id='gold_serving',\n    default_args=default_args,\n    schedule_interval=None,  # 수동 트리거만\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,\n    tags=['gold', 'batch'],\n) as dag:\n\n    run_gold_job = SparkSubmitOperator(\n        task_id='run_gold_serving',\n        application='/opt/spark-jobs/airadar-spark.jar',\n        java_class='com.mcp.airadar.spark.GoldServingJob',\n        conn_id='spark_default',\n        application_args=['--date', '{{ ds }}'],\n        conf=SPARK_CONF,\n    )\n
1651749510320228	/opt/airflow/dags/crawl_news_to_kafka_dag.py	2026-03-29 13:34:44.766401+00	from __future__ import annotations\n\nfrom datetime import datetime, timedelta\nimport os\n\nimport requests\nfrom airflow import DAG\nfrom airflow.operators.python import PythonOperator\n\n\ndefault_args = {\n    "owner": "ai-rader",\n    "retries": 2,\n    "retry_delay": timedelta(minutes=3),\n    "email_on_failure": False,\n    "depends_on_past": False,\n    "execution_timeout": timedelta(minutes=20),\n}\n\n\ndef _trigger_crawl(payload: dict) -> None:\n    base_url = os.getenv("CRAWLING_API_BASE_URL", "http://host.docker.internal:8002").rstrip("/")\n    url = f"{base_url}/crawl/jobs"\n    resp = requests.post(url, json=payload, timeout=300)\n    resp.raise_for_status()\n    data = resp.json()\n    print(\n        "crawl done",\n        {\n            "domain": data.get("domain"),\n            "provider": data.get("provider"),\n            "crawled_count": data.get("crawled_count"),\n            "failed_count": data.get("failed_count"),\n            "kafka": (data.get("metadata") or {}).get("kafka"),\n        },\n    )\n\n\nwith DAG(\n    dag_id="crawl_news_to_kafka",\n    default_args=default_args,\n    schedule_interval="*/30 * * * *",\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,    # 동시 실행 1개로 제한 (크롤링 서버 과부하 방지)\n    tags=["crawl", "news", "kafka"],\n) as dag:\n    crawl_aitimes = PythonOperator(\n        task_id="crawl_aitimes",\n        python_callable=_trigger_crawl,\n        op_kwargs={\n            "payload": {\n                "domain": "news",\n                "provider": "aitimes",\n                "targets": ["ai_industry", "ai_company"],\n                "max_pages_per_target": 1,\n                "max_articles": 40,\n            }\n        },\n    )\n\n    crawl_gdelt = PythonOperator(\n        task_id="crawl_gdelt",\n        python_callable=_trigger_crawl,\n        op_kwargs={\n            "payload": {\n                "domain": "news",\n                "provider": "gdelt",\n                "window_minutes": 60,\n                "max_articles": 120,\n            }\n        },\n    )\n\n    [crawl_aitimes, crawl_gdelt]\n
49297176863434649	/opt/airflow/dags/silver_refinement_dag.py	2026-03-29 13:34:44.8554+00	from datetime import datetime, timedelta\n\nfrom airflow import DAG\nfrom airflow.operators.bash import BashOperator\nfrom airflow.providers.apache.spark.operators.spark_submit import SparkSubmitOperator\nfrom airflow.sensors.external_task import ExternalTaskSensor\nfrom airflow.models import DagRun\nfrom airflow.utils.state import State\n\ndefault_args = {\n    'owner': 'ai-radar',\n    'retries': 2,\n    'retry_delay': timedelta(minutes=5),\n    'email_on_failure': False,\n    'depends_on_past': False,\n    'execution_timeout': timedelta(hours=12),  # 로컬 AI 서버 기준 충분한 여유\n}\n\nSPARK_CONF = {\n    'spark.master': 'spark://spark-master:7077',\n    'spark.executor.memory': '1g',\n    'spark.executor.cores': '1',\n    'spark.executor.instances': '2',   # OOM 방지 (15g 서버 기준 2개 제한)\n    'spark.driver.memory': '1g',\n    'spark.sql.extensions': 'io.delta.sql.DeltaSparkSessionExtension',\n    'spark.sql.catalog.spark_catalog': 'org.apache.spark.sql.delta.catalog.DeltaCatalog',\n}\n\nwith DAG(\n    dag_id='silver_refinement',\n    default_args=default_args,\n    schedule_interval=None,  # 수동 트리거만 (로컬 AI 서버 처리 시간 고려)\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,    # 동시 실행 1개로 제한 (Spark OOM 방지)\n    tags=['silver', 'batch'],\n    params={\n        # 한 번 실행당 처리할 최대 건수. 0 이면 전체 처리.\n        'limit': 200,\n        # True 이면 기존 Silver를 replaceWhere로 덮어쓰며 전체 재분석 (companies 등 갱신 목적)\n        'reprocess': False,\n        # 처리할 날짜. 미지정 시 {{ ds }} (DAG 실행일) 사용.\n        'date': '',\n    },\n) as dag:\n\n    def get_latest_bronze_execution_date(execution_date, **kwargs):\n        """가장 최근 성공한 bronze_kafka_ingestion run의 execution_date 반환"""\n        from airflow.utils.session import create_session\n        with create_session() as session:\n            last_run = (\n                session.query(DagRun)\n                .filter(\n                    DagRun.dag_id == 'bronze_kafka_ingestion',\n                    DagRun.state == State.SUCCESS,\n                )\n                .order_by(DagRun.execution_date.desc())\n                .first()\n            )\n        if last_run:\n            return last_run.execution_date\n        return execution_date\n\n    # Bronze 적재 완료 후 Silver 정제 실행\n    wait_for_bronze = ExternalTaskSensor(\n        task_id='wait_for_bronze_ingestion',\n        external_dag_id='bronze_kafka_ingestion',\n        external_task_id=None,   # DAG 전체 완료 대기\n        execution_date_fn=get_latest_bronze_execution_date,\n        timeout=3600,\n        poke_interval=60,\n        mode='reschedule',       # slot을 점유하지 않고 대기\n    )\n\n    # news → paper → github 순차 실행 (Spark driver 동시 실행 시 OOM 방지)\n    refine_news = SparkSubmitOperator(\n        task_id='refine_news',\n        application='/opt/spark-jobs/airadar-spark.jar',\n        java_class='com.mcp.airadar.spark.SilverRefinementJob',\n        conn_id='spark_default',\n        application_args=[\n            '--date', '{{ params.date if params.date else ds }}',\n            '--source-type', 'news',\n            '--limit', '{{ params.limit }}',\n            '--reprocess', '{{ params.reprocess }}',\n        ],\n        conf=SPARK_CONF,\n    )\n\n    refine_paper = SparkSubmitOperator(\n        task_id='refine_paper',\n        application='/opt/spark-jobs/airadar-spark.jar',\n        java_class='com.mcp.airadar.spark.SilverRefinementJob',\n        conn_id='spark_default',\n        application_args=[\n            '--date', '{{ params.date if params.date else ds }}',\n            '--source-type', 'paper',\n            '--limit', '{{ params.limit }}',\n            '--reprocess', '{{ params.reprocess }}',\n        ],\n        conf=SPARK_CONF,\n    )\n\n    refine_github = SparkSubmitOperator(\n        task_id='refine_github',\n        application='/opt/spark-jobs/airadar-spark.jar',\n        java_class='com.mcp.airadar.spark.SilverRefinementJob',\n        conn_id='spark_default',\n        application_args=[\n            '--date', '{{ params.date if params.date else ds }}',\n            '--source-type', 'github',\n            '--limit', '{{ params.limit }}',\n            '--reprocess', '{{ params.reprocess }}',\n        ],\n        conf=SPARK_CONF,\n    )\n\n    # Silver 처리 완료 후 Materialized View REFRESH\n    # CONCURRENTLY: 조회를 막지 않고 갱신 (unique index 필요)\n    refresh_view = BashOperator(\n        task_id='refresh_tech_contents_view',\n        bash_command=(\n            'PGPASSWORD="$POSTGRES_PASSWORD" psql '\n            '-h "$POSTGRES_HOST" -p "$POSTGRES_PORT" '\n            '-U "$POSTGRES_USER" -d "$POSTGRES_DB" '\n            '-c "REFRESH MATERIALIZED VIEW CONCURRENTLY public.tech_contents_view;"'\n        ),\n        execution_timeout=timedelta(minutes=10),\n    )\n\n    wait_for_bronze >> refine_news >> refine_paper >> refine_github >> refresh_view\n
29158519568402977	/opt/airflow/dags/bronze_ingestion_dag.py	2026-03-29 13:34:44.725401+00	from datetime import datetime, timedelta\n\nfrom airflow import DAG\nfrom airflow.providers.apache.spark.operators.spark_submit import SparkSubmitOperator\nfrom airflow.utils.task_group import TaskGroup\n\ndefault_args = {\n    'owner': 'ai-radar',\n    'retries': 2,\n    'retry_delay': timedelta(minutes=5),\n    'email_on_failure': False,\n    'depends_on_past': False,\n    'execution_timeout': timedelta(hours=2),\n}\n\nSPARK_CONF = {\n    'spark.master': 'spark://spark-master:7077',\n    'spark.executor.memory': '2g',\n    'spark.executor.cores': '2',\n    'spark.sql.extensions': 'io.delta.sql.DeltaSparkSessionExtension',\n    'spark.sql.catalog.spark_catalog': 'org.apache.spark.sql.delta.catalog.DeltaCatalog',\n}\n\n# Kafka 준비 완료 시 SPARK_CONF_KAFKA로 교체\nSPARK_CONF_KAFKA = {\n    **SPARK_CONF,\n    'spark.streaming.stopGracefullyOnShutdown': 'true',\n}\n\n# ── [현재] Phase 1 ─────────────────────────────────────────────────────────────\n# Crawling Server → Spark → Bronze Delta Lake (HTTP 직접 호출)\n# Kafka가 준비되면 아래 Phase 2 DAG로 교체한다\n# ──────────────────────────────────────────────────────────────────────────────\nwith DAG(\n    dag_id='bronze_ingestion',\n    default_args=default_args,\n    schedule_interval='@hourly',\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,              # 동시 실행 1개로 제한 (Spark OOM 방지)\n    is_paused_upon_creation=True,   # Phase 2(Kafka) 전환으로 비활성화\n    tags=['bronze', 'batch'],\n) as dag:\n\n    # news / paper / github 를 TaskGroup으로 병렬 실행\n    # 장애 격리: 하나 실패해도 나머지는 계속 실행\n    with TaskGroup('bronze_ingestion_tasks') as ingestion_group:\n        for source in ['news', 'paper', 'github']:\n            SparkSubmitOperator(\n                task_id=f'ingest_{source}',\n                application='/opt/spark-jobs/airadar-spark.jar',\n                java_class='com.mcp.airadar.spark.BronzeIngestionJob',\n                conn_id='spark_default',\n                application_args=['--date', '{{ ds }}', '--source-type', source],\n                conf=SPARK_CONF,\n            )\n\n\n# ── [예정] Phase 2 ─────────────────────────────────────────────────────────────\n# Kafka 준비 완료 후 아래 DAG를 활성화한다.\n# 1. 이 파일에서 bronze_ingestion DAG를 비활성화(is_paused_upon_creation=True)\n# 2. bronze_kafka_ingestion DAG를 활성화\n# 3. silver_refinement_dag.py의 external_dag_id를 'bronze_kafka_ingestion'으로 변경\n# ──────────────────────────────────────────────────────────────────────────────\nwith DAG(\n    dag_id='bronze_kafka_ingestion',\n    default_args=default_args,\n    schedule_interval='@hourly',\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,              # 동시 실행 1개로 제한 (Spark OOM 방지)\n    is_paused_upon_creation=False,  # Phase 2 활성화\n    tags=['bronze', 'kafka', 'streaming'],\n) as kafka_dag:\n\n    # Trigger.AvailableNow() 사용 — 현재 Kafka 메시지 모두 처리 후 종료\n    # 체크포인트가 오프셋을 관리하므로 재실행 시 중복 처리 없음\n    with TaskGroup('bronze_kafka_tasks') as kafka_group:\n        for source in ['news', 'github', 'paper']:\n            SparkSubmitOperator(\n                task_id=f'consume_{source}',\n                application='/opt/spark-jobs/airadar-spark.jar',\n                java_class='com.mcp.airadar.spark.KafkaBronzeConsumerJob',\n                conn_id='spark_default',\n                application_args=['--source-type', source],\n                conf=SPARK_CONF_KAFKA,\n            )\n
2927332109597171	/opt/airflow/dags/recommendation_batch_dag.py	2026-03-29 13:34:44.8324+00	from datetime import datetime, timedelta\n\nfrom airflow import DAG\nfrom airflow.providers.apache.spark.operators.spark_submit import SparkSubmitOperator\nfrom airflow.operators.python import PythonOperator\nfrom airflow.exceptions import AirflowSkipException\n\ndefault_args = {\n    'owner': 'ai-radar',\n    'retries': 1,\n    'retry_delay': timedelta(minutes=10),\n    'email_on_failure': False,\n    'depends_on_past': False,\n    'execution_timeout': timedelta(hours=2),\n}\n\n# ALS Job: driver는 Airflow 컨테이너 내 실행 → 메모리 최소화, executor는 spark-master에서 실행\nSPARK_CONF = {\n    'spark.master': 'spark://spark-master:7077',\n    'spark.executor.memory': '2g',\n    'spark.executor.cores': '2',\n    'spark.executor.instances': '1',\n    'spark.driver.memory': '512m',\n    'spark.driver.memoryOverhead': '256m',\n    # ALS 반복 학습 중 broadcast 최적화\n    'spark.sql.autoBroadcastJoinThreshold': '-1',\n    'spark.serializer': 'org.apache.spark.serializer.KryoSerializer',\n}\n\n\ndef check_min_event_count(**context):\n    """\n    search_logs에 충분한 이벤트가 쌓였는지 확인.\n    30일치 로그인 이벤트가 100건 미만이면 ALS 학습 의미 없음 → skip.\n    """\n    import psycopg2\n    import os\n\n    conn = psycopg2.connect(\n        host=os.environ['POSTGRES_HOST'],\n        port=os.environ.get('POSTGRES_PORT', '5432'),\n        dbname=os.environ['POSTGRES_DB'],\n        user=os.environ['POSTGRES_USER'],\n        password=os.environ['POSTGRES_PASSWORD'],\n    )\n    try:\n        with conn.cursor() as cur:\n            cur.execute("""\n                SELECT COUNT(*)\n                FROM search_logs\n                WHERE occurred_at >= NOW() - INTERVAL '30 days'\n                  AND user_id IS NOT NULL\n                  AND event_type IN ('ARTICLE_LIKED', 'ARTICLE_BOOKMARKED', 'ARTICLE_VIEWED')\n            """)\n            count = cur.fetchone()[0]\n\n        if count < 10:\n            raise AirflowSkipException(\n                f"[Rec Batch] 이벤트 수 부족 ({count}건) — ALS 학습 skip. "\n                "10건 이상 쌓이면 자동 재시작됩니다."\n            )\n\n        context['ti'].xcom_push(key='event_count', value=count)\n        print(f"[Rec Batch] 충분한 이벤트 확인: {count}건 → ALS 학습 진행")\n    finally:\n        conn.close()\n\n\nwith DAG(\n    dag_id='recommendation_batch',\n    default_args=default_args,\n    schedule_interval='0 2 * * *',  # 매일 새벽 2시 (Gold 완료 후 여유 확보)\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,\n    tags=['recommendation', 'batch', 'als'],\n) as dag:\n\n    # 이벤트 수 사전 확인 (ALS는 cold data에서 의미 없음)\n    check_events = PythonOperator(\n        task_id='check_min_event_count',\n        python_callable=check_min_event_count,\n    )\n\n    # ALS 협업 필터링 Spark Job\n    # - PostgreSQL search_logs 직접 읽기 (Kafka Delta Lake 대체)\n    # - user-item 행렬 → ALS 학습 → user_recommendations 저장\n    run_recommendation_job = SparkSubmitOperator(\n        task_id='run_recommendation_batch',\n        application='/opt/spark-jobs/airadar-spark.jar',\n        java_class='com.mcp.airadar.spark.CollaborativeFilteringJob',\n        conn_id='spark_default',\n        application_args=['--date', '{{ ds }}'],\n        conf=SPARK_CONF,\n    )\n\n    check_events >> run_recommendation_job\n
9843179336971036	/opt/airflow/dags/crawl_github_to_kafka_dag.py	2026-03-29 13:34:44.745401+00	from __future__ import annotations\n\nfrom datetime import datetime, timedelta\nimport os\n\nimport requests\nfrom airflow import DAG\nfrom airflow.operators.python import PythonOperator\n\n\ndefault_args = {\n    "owner": "ai-rader",\n    "retries": 2,\n    "retry_delay": timedelta(minutes=5),\n    "email_on_failure": False,\n    "depends_on_past": False,\n    "execution_timeout": timedelta(minutes=45),\n}\n\n\ndef _trigger_github_crawl() -> None:\n    base_url = os.getenv("CRAWLING_API_BASE_URL", "http://host.docker.internal:8002").rstrip("/")\n    url = f"{base_url}/crawl/jobs"\n    payload = {\n        "domain": "github_archive",\n        "provider": "github_trending_archive",\n        "max_articles": 100,\n        "github_window_minutes": 180,\n        "github_min_stars": 50,\n        "github_top_n": 100,\n    }\n    resp = requests.post(url, json=payload, timeout=600)\n    resp.raise_for_status()\n    data = resp.json()\n    print(\n        "crawl done",\n        {\n            "domain": data.get("domain"),\n            "provider": data.get("provider"),\n            "crawled_count": data.get("crawled_count"),\n            "failed_count": data.get("failed_count"),\n            "kafka": (data.get("metadata") or {}).get("kafka"),\n        },\n    )\n\n\nwith DAG(\n    dag_id="crawl_github_to_kafka",\n    default_args=default_args,\n    schedule_interval="0 */3 * * *",\n    start_date=datetime(2025, 1, 1),\n    catchup=False,\n    max_active_runs=1,    # 동시 실행 1개로 제한 (크롤링 서버 과부하 방지)\n    tags=["crawl", "github", "kafka"],\n) as dag:\n    crawl_github_archive = PythonOperator(\n        task_id="crawl_github_trending_archive",\n        python_callable=_trigger_github_crawl,\n    )\n
